+    bookmarks: attachTagsToBookmarks(bookmarks, userId).map((bookmark) => {
+      const { user_id: _userId, tags: bookmarkTags, ...exportedBookmark } = bookmark;
+      const folder = folders.find((item) => item.id === bookmark.folder_id);
+      return {
+        ...exportedBookmark,
+        folder: folder?.name ?? null,
+        tag_ids: bookmarkTags.map((tag) => tag.id),
+        tags: bookmarkTags.map((tag) => tag.name),
+      };
+    }),
+  };
+}
+
+function validateImportPayload(body: unknown): ExportPayload | string {
+  if (typeof body !== "object" || body === null || Array.isArray(body)) {
+    return "Request body must be an object";
+  }
+
+  const input = body as Record<string, unknown>;
+  if (input.version !== undefined && input.version !== 1) {
+    return "version must be 1";
+  }
+
+  if (!Array.isArray(input.folders) || !Array.isArray(input.tags) || !Array.isArray(input.bookmarks)) {
+    return "folders, tags, and bookmarks must be arrays";
+  }
+
+  const folders: ExportedFolder[] = [];
+  for (const folder of input.folders) {
+    if (typeof folder !== "object" || folder === null || Array.isArray(folder)) {
+      return "folders must contain objects";
+    }
+
+    const item = folder as Record<string, unknown>;
+    if (!isNonEmptyString(item.name)) {
+      return "folder name must be a non-empty string";
+    }
+
+    if (item.id !== undefined && (typeof item.id !== "number" || !Number.isInteger(item.id) || item.id <= 0)) {
+      return "folder id must be a positive integer";
+    }
+
+    folders.push({ id: item.id as number | undefined, name: item.name.trim() });
+  }
+
+  const tags: ExportedTag[] = [];
+  for (const tag of input.tags) {
+    if (typeof tag !== "object" || tag === null || Array.isArray(tag)) {
+      return "tags must contain objects";
+    }
+
+    const item = tag as Record<string, unknown>;
+    if (!isNonEmptyString(item.name)) {
+      return "tag name must be a non-empty string";
+    }
+
+    if (item.id !== undefined && (typeof item.id !== "number" || !Number.isInteger(item.id) || item.id <= 0)) {
+      return "tag id must be a positive integer";
+    }
+
+    tags.push({ id: item.id as number | undefined, name: item.name.trim() });
+  }
+
+  const bookmarks: ExportedBookmark[] = [];
+  for (const bookmark of input.bookmarks) {
+    if (typeof bookmark !== "object" || bookmark === null || Array.isArray(bookmark)) {
+      return "bookmarks must contain objects";
+    }
+
+    const item = bookmark as Record<string, unknown>;
+    if (!isNonEmptyString(item.url) || !isValidUrl(item.url)) {
+      return "bookmark url must be a valid URL";
+    }
+
+    if (!isNonEmptyString(item.title)) {
+      return "bookmark title must be a non-empty string";
+    }
+
+    if (item.id !== undefined && (typeof item.id !== "number" || !Number.isInteger(item.id) || item.id <= 0)) {
+      return "bookmark id must be a positive integer";
+    }
+
+    if (item.description !== undefined && item.description !== null && typeof item.description !== "string") {
+      return "bookmark description must be a string or null";
+    }
+
+    if (
+      item.folder_id !== undefined &&
+      item.folder_id !== null &&
+      (typeof item.folder_id !== "number" || !Number.isInteger(item.folder_id) || item.folder_id <= 0)
+    ) {
+      return "bookmark folder_id must be a positive integer or null";
+    }
+
+    if (item.folder !== undefined && item.folder !== null && !isNonEmptyString(item.folder)) {
+      return "bookmark folder must be a non-empty string or null";
+    }
+
+    if (
+      item.tag_ids !== undefined &&
+      (!Array.isArray(item.tag_ids) ||
+        !item.tag_ids.every((tagId) => typeof tagId === "number" && Number.isInteger(tagId) && tagId > 0))
+    ) {
+      return "bookmark tag_ids must be positive integers";
+    }
+
+    if (
+      item.tags !== undefined &&
+      (!Array.isArray(item.tags) || !item.tags.every((tagName) => isNonEmptyString(tagName)))
+    ) {
+      return "bookmark tags must be non-empty strings";
+    }
+
+    bookmarks.push({
+      id: item.id as number | undefined,
+      url: item.url.trim(),
+      title: item.title.trim(),
+      description: item.description === undefined ? null : (item.description as string | null),
+      folder_id: item.folder_id as number | null | undefined,
+      folder: item.folder === undefined || item.folder === null ? null : item.folder.trim(),
+      tag_ids: item.tag_ids === undefined ? [] : [...new Set(item.tag_ids as number[])],
+      tags: item.tags === undefined ? [] : [...new Set((item.tags as string[]).map((tagName) => tagName.trim()))],
+    });
+  }
+
+  return {
+    version: 1,
+    folders,
+    tags,
+    bookmarks,
+  };
+}
+
+function importPayloadForUser(userId: number, payload: ExportPayload): ImportSummary {
+  const summary: ImportSummary = { imported: 0, skipped: 0, updated: 0 };
+
+  const runImport = db.transaction(() => {
+    const folderIds = new Map<number, number>();
+    const foldersByName = new Map<string, Folder>();
+    const tagIds = new Map<number, number>();
+    const tagsByName = new Map<string, Tag>();
+    const now = new Date().toISOString();
+
+    for (const existingFolder of db
+      .prepare("SELECT * FROM folders WHERE user_id = ? ORDER BY id ASC")
+      .all(userId) as Folder[]) {
+      foldersByName.set(existingFolder.name, existingFolder);
+    }
+
+    for (const existingTag of db.prepare("SELECT * FROM tags WHERE user_id = ? ORDER BY id ASC").all(userId) as Tag[]) {
+      tagsByName.set(existingTag.name, existingTag);
+    }
+
+    for (const folder of payload.folders) {
+      const existing = foldersByName.get(folder.name) ?? (selectFolderByName.get(folder.name, userId) as Folder | undefined);
+      if (existing) {
+        summary.skipped += 1;
+        if (folder.id !== undefined) {
+          folderIds.set(folder.id, existing.id);
+        }
+        foldersByName.set(folder.name, existing);
+        continue;
+      }
+
+      const result = db
+        .prepare(
+          `
+            INSERT INTO folders (user_id, name, created_at, updated_at)
+            VALUES (?, ?, ?, ?)
+          `,
+        )
+        .run(userId, folder.name, now, now);
+      const created = getFolder(Number(result.lastInsertRowid), userId) as Folder;
+      summary.imported += 1;
+      foldersByName.set(folder.name, created);
+      if (folder.id !== undefined) {
+        folderIds.set(folder.id, created.id);
+      }
+    }
+
+    for (const tag of payload.tags) {
+      const existing = tagsByName.get(tag.name) ?? (selectTagByName.get(tag.name, userId) as Tag | undefined);
+      if (existing) {
+        summary.skipped += 1;
+        if (tag.id !== undefined) {
+          tagIds.set(tag.id, existing.id);
+        }
+        tagsByName.set(tag.name, existing);
+        continue;
+      }
+
+      const result = db
+        .prepare(
+          `
+            INSERT INTO tags (user_id, name, created_at, updated_at)
+            VALUES (?, ?, ?, ?)
+          `,
+        )
+        .run(userId, tag.name, now, now);
+      const created = getTag(Number(result.lastInsertRowid), userId) as Tag;
+      summary.imported += 1;
+      tagsByName.set(tag.name, created);
+      if (tag.id !== undefined) {
+        tagIds.set(tag.id, created.id);
+      }
+    }
+
+    for (const bookmark of payload.bookmarks) {
+      let folderId: number | null = null;
+      if (bookmark.folder_id !== undefined && bookmark.folder_id !== null) {
+        folderId = folderIds.get(bookmark.folder_id) ?? null;
+      }
+      if (folderId === null && bookmark.folder) {
+        folderId = foldersByName.get(bookmark.folder)?.id ?? null;
+      }
+
+      const resolvedTagIds = new Set<number>();
+      for (const sourceTagId of bookmark.tag_ids ?? []) {
+        const resolvedTagId = tagIds.get(sourceTagId);
+        if (resolvedTagId !== undefined) {
+          resolvedTagIds.add(resolvedTagId);
+        }
+      }
+      for (const tagName of bookmark.tags ?? []) {
+        let tag = tagsByName.get(tagName);
+        if (!tag) {
+          const result = db
+            .prepare(
+              `
+                INSERT INTO tags (user_id, name, created_at, updated_at)
+                VALUES (?, ?, ?, ?)
+              `,
+            )
+            .run(userId, tagName, now, now);
+          tag = getTag(Number(result.lastInsertRowid), userId) as Tag;
+          tagsByName.set(tagName, tag);
+          summary.imported += 1;
+        }
+        resolvedTagIds.add(tag.id);
+      }
+
+      const desiredTagIds = [...resolvedTagIds].sort((left, right) => left - right);
+      const normalizedUrl = normalizeUrl(bookmark.url);
+      const existing = getBookmarkByNormalizedUrl(userId, normalizedUrl);
+      if (!existing) {
+        const result = db
+          .prepare(
+            `
+              INSERT INTO bookmarks (user_id, url, title, description, folder_id, version, created_at, updated_at)
+              VALUES (?, ?, ?, ?, ?, 1, ?, ?)
+            `,
+          )
+          .run(userId, normalizedUrl, bookmark.title, bookmark.description ?? null, folderId, now, now);
+        setBookmarkTags(Number(result.lastInsertRowid), desiredTagIds);
+        summary.imported += 1;
+        continue;
+      }
+
+      const existingTagIds = getCurrentBookmarkTagIds(existing.id);
+      const needsUpdate =
+        existing.url !== normalizedUrl ||
+        existing.title !== bookmark.title ||
+        existing.description !== (bookmark.description ?? null) ||
+        existing.folder_id !== folderId ||
+        !sameNumberSet(existingTagIds, desiredTagIds);
+
+      if (!needsUpdate) {
+        summary.skipped += 1;
+        continue;
+      }
+
+      db.prepare(
+        `
+          UPDATE bookmarks
+          SET url = ?, title = ?, description = ?, folder_id = ?, version = version + 1, updated_at = ?
+          WHERE id = ? AND user_id = ?
+        `,
+      ).run(normalizedUrl, bookmark.title, bookmark.description ?? null, folderId, new Date().toISOString(), existing.id, userId);
+      setBookmarkTags(existing.id, desiredTagIds);
+      summary.updated += 1;
+    }
+  });
+
+  runImport();
+  return summary;
+}
+
+function validateBookmarkInput(body: unknown, required: boolean, userId: number): string | null {
+  if (typeof body !== "object" || body === null) {
+    return "Request body must be an object";
+  }
+
+  const input = body as Record<string, unknown>;
+
+  const titleError = required
+    ? validateRequiredNonEmptyString(input, "title")
+    : validateOptionalNonEmptyString(input, "title");
+  if (titleError) {
+    return titleError;
+  }
+
+  const urlError = required
+    ? validateRequiredNonEmptyString(input, "url")
+    : validateOptionalNonEmptyString(input, "url");
+  if (urlError) {
+    return urlError;
+  }
+
+  if ((required || "url" in input) && !isValidUrl(input.url)) {
+    return "url must be a valid URL";
+  }
+
+  if ("description" in input && input.description !== null && typeof input.description !== "string") {
+    return "description must be a string or null";
+  }
+
+  if ("folder_id" in input) {
+    const folderIdError = validateFolderId(input.folder_id, userId);
+    if (folderIdError) {
+      return folderIdError;
+    }
+  }
+
+  if ("tag_ids" in input) {
+    const tagIds = parseTagIds(input.tag_ids, userId);
+    if (typeof tagIds === "string") {
+      return tagIds;
+    }
+  }
+
+  return null;
+}
+
+function validateBookmarkUpdateVersion(input: Record<string, unknown>): string | null {
+  if (!("version" in input)) {
+    return "version is required";
+  }
+
+  if (typeof input.version !== "number" || !Number.isInteger(input.version) || input.version <= 0) {
+    return "version must be a positive integer";
+  }
+
+  return null;
+}
+
+function validateFolderInput(body: unknown, required: boolean): string | null {
+  if (typeof body !== "object" || body === null) {
+    return "Request body must be an object";
+  }
+
+  const input = body as Record<string, unknown>;
+  return required ? validateRequiredNonEmptyString(input, "name") : validateOptionalNonEmptyString(input, "name");
+}
+
+function validateTagInput(body: unknown, required: boolean): string | null {
+  if (typeof body !== "object" || body === null) {
+    return "Request body must be an object";
+  }
+
+  const input = body as Record<string, unknown>;
+  return required ? validateRequiredNonEmptyString(input, "name") : validateOptionalNonEmptyString(input, "name");
+}
+
+function parseTagFilters(tag: unknown, tags: unknown): string[] | string {
+  if (tag === undefined && tags === undefined) {
+    return [];
+  }
+
+  if (
+    (tag !== undefined && (Array.isArray(tag) || typeof tag !== "string")) ||
+    (tags !== undefined && (Array.isArray(tags) || typeof tags !== "string"))
+  ) {
+    return "tag filters must be strings";
+  }
+
+  const names = [tag, tags]
+    .filter((value): value is string => typeof value === "string")
+    .flatMap((value) => value.split(","))
+    .map((name) => name.trim())
+    .filter((name) => name.length > 0);
+
+  return [...new Set(names)];
+}
+
+function parseSearchQuery(q: unknown): { value: string | null; error: string | null } {
+  if (q === undefined) {
+    return { value: null, error: null };
+  }
+
+  if (Array.isArray(q) || typeof q !== "string") {
+    return { value: null, error: "q must be a string" };
+  }
+
+  if (q.length > 200) {
+    return { value: null, error: "q must be 200 characters or fewer" };
+  }
+
+  const trimmed = q.trim();
+  return { value: trimmed.length === 0 ? null : trimmed, error: null };
+}
+
+function escapeLikePattern(value: string): string {
+  return value.replace(/[\\%_]/g, "\\$&");
+}
