+  const id = parseId(req.params.id);
+  const existing = id === null ? undefined : getBookmark(id, userId);
+
+  if (!existing) {
+    if (id !== null && isSharedBookmarkForUser(id, userId)) {
+      return res.status(403).json({ error: "Shared folders are read-only" });
+    }
+
+    return res.status(404).json({ error: "Bookmark not found" });
+  }
+
+  if (
+    typeof req.body === "object" &&
+    req.body !== null &&
+    !Array.isArray(req.body) &&
+    typeof (req.body as { folder_id?: unknown }).folder_id === "number" &&
+    isSharedFolderForUser((req.body as { folder_id: number }).folder_id, userId)
+  ) {
+    return res.status(403).json({ error: "Shared folders are read-only" });
+  }
+
+  const validationError = validateBookmarkInput(req.body, false, userId);
+  if (validationError) {
+    return res.status(400).json({ error: validationError });
+  }
+
+  const input = req.body as {
+    url?: string;
+    title?: string;
+    description?: string | null;
+    folder_id?: number | null;
+    tag_ids?: number[];
+    version: number;
+  };
+  const versionError = validateBookmarkUpdateVersion(input);
+  if (versionError) {
+    return res.status(400).json({ error: versionError });
+  }
+
+  const bookmarkTagIds = input.tag_ids === undefined ? undefined : (parseTagIds(input.tag_ids, userId) as number[]);
+  const updatedAt = new Date().toISOString();
+
+  const updateBookmark = db.transaction(() => {
+    const result = db.prepare(
+      `
+        UPDATE bookmarks
+        SET url = ?, title = ?, description = ?, folder_id = ?, version = version + 1, updated_at = ?
+        WHERE id = ? AND user_id = ? AND version = ?
+      `,
+    ).run(
+      input.url === undefined ? existing.url : input.url.trim(),
+      input.title === undefined ? existing.title : input.title.trim(),
+      input.description === undefined ? existing.description : input.description,
+      input.folder_id === undefined ? existing.folder_id : input.folder_id,
+      updatedAt,
+      existing.id,
+      userId,
+      input.version,
+    );
+
+    if (result.changes === 0) {
+      return false;
+    }
+
+    if (bookmarkTagIds !== undefined) {
+      setBookmarkTags(existing.id, bookmarkTagIds);
+    }
+
+    return true;
+  });
+
+  const updated = updateBookmark();
+
+  if (!updated) {
+    const current = getBookmark(existing.id, userId);
+    if (!current) {
+      return res.status(404).json({ error: "Bookmark not found" });
+    }
+
